"use strict";

const crypto = require("crypto");
const fs = require("fs");
const path = require("path");
const vm = require("vm");

const root = path.resolve(__dirname, "..");
const htmlPath = path.join(root, "frontend", "index.html");
const babelPath = path.join(root, "frontend", "vendor", "babel.min.js");
const bundlePath = path.join(root, "frontend", "app.bundle.js");

const html = fs.readFileSync(htmlPath, "utf8");
const sourceMatch = html.match(
  /<script\s+type=["']text\/plain["']\s+id=["']app-source["']>([\s\S]*?)<\/script>/i,
);

if (!sourceMatch) {
  throw new Error("frontend/index.html does not contain #app-source");
}

const source = sourceMatch[1].replace(/\r\n/g, "\n").replace(/^\n/, "");
const sourceHash = crypto.createHash("sha256").update(source, "utf8").digest("hex");
const babelCode = fs.readFileSync(babelPath, "utf8");
const context = { console };
context.globalThis = context;
context.self = context;
context.window = context;
vm.createContext(context);
vm.runInContext(babelCode, context, { filename: babelPath });

if (!context.Babel || typeof context.Babel.transform !== "function") {
  throw new Error("Bundled Babel runtime could not be initialized");
}

const compiled = context.Babel.transform(source, {
  presets: ["react"],
  sourceType: "script",
  compact: false,
  comments: true,
}).code;

const banner = [
  "/* Alpha Station precompiled frontend bundle.",
  ` * app-source-sha256: ${sourceHash}`,
  " * Generated by scripts/build_frontend_bundle.js; do not edit manually.",
  " */",
  "",
].join("\n");

fs.writeFileSync(bundlePath, `${banner}${compiled}\n`, "utf8");
console.log(`Built ${path.relative(root, bundlePath)} (${sourceHash.slice(0, 12)})`);
